node -e "
const XLSX = require('xlsx');

// Create a new workbook
const wb = XLSX.utils.book_new();

// Create an empty array of arrays large enough for row 43, col 7 (G43)
const data = [];
for (let i = 0; i < 43; i++) {
  data.push([]);
}
// Row 43 (index 42), Column 7 / col G (index 6)
data[42][6] = 129;

// Create the worksheet from the array
const ws = XLSX.utils.aoa_to_sheet(data);

// Append sheet named 'Travel' to workbook
XLSX.utils.book_append_sheet(wb, ws, 'Travel');

// Write the file
XLSX.writeFile(wb, 'data/travel_expenses.xlsx');

// Verify
const wb2 = XLSX.readFile('data/travel_expenses.xlsx');
const ws2 = wb2.Sheets['Travel'];
const cell = ws2['G43'];
console.log('Sheet: Travel');
console.log('Cell G43 (row 43, col 7):', cell ? cell.v : 'empty');
"
